-- Undated feeds: parser_config undated=fetch_time on 5 feeds (A), then a batched 14-day backfill (B). Generated by Build-Sql.py.
-- B runs in autocommit batches: never wrap this file in BEGIN. Reverse: reverse.sql.
\set ON_ERROR_STOP on
SELECT 'undated|' || publisher_id || '|' || count(*) || '|in window=' || count(*) FILTER (WHERE fetched_at > now() - interval '14 days')
  FROM articles WHERE publisher_id IN (968, 3138, 1047, 1015, 171) AND published_at IS NULL GROUP BY publisher_id ORDER BY publisher_id;
SET lock_timeout = '5s';
BEGIN;
DO $do$
DECLARE k int;
BEGIN
  UPDATE feeds SET parser_config = '{"undated": "fetch_time"}'::jsonb
   WHERE publisher_id = 968 AND feed_url = 'https://www.hani.co.kr/rss/' AND feed_type = 'rss' AND enabled AND parser_config = '{}'::jsonb;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '968: % feed rows with an empty parser_config, expected 1 - nothing changed', k; END IF;
  UPDATE feeds SET parser_config = '{"undated": "fetch_time"}'::jsonb
   WHERE publisher_id = 3138 AND feed_url = 'https://feeds.leparisien.fr/leparisien/rss' AND feed_type = 'rss' AND enabled AND parser_config = '{}'::jsonb;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '3138: % feed rows with an empty parser_config, expected 1 - nothing changed', k; END IF;
  UPDATE feeds SET parser_config = '{"undated": "fetch_time"}'::jsonb
   WHERE publisher_id = 1047 AND feed_url = 'https://www.presstv.ir/rss.xml' AND feed_type = 'rss' AND enabled AND parser_config = '{}'::jsonb;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '1047: % feed rows with an empty parser_config, expected 1 - nothing changed', k; END IF;
  UPDATE feeds SET parser_config = '{"undated": "fetch_time"}'::jsonb
   WHERE publisher_id = 1015 AND feed_url = 'https://kathmandupost.com/rss' AND feed_type = 'rss' AND enabled AND parser_config = '{}'::jsonb;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '1015: % feed rows with an empty parser_config, expected 1 - nothing changed', k; END IF;
  UPDATE feeds SET parser_config = '{"undated": "fetch_time"}'::jsonb
   WHERE publisher_id = 171 AND feed_url = 'https://www.elkhabar.com/feed' AND feed_type = 'rss' AND enabled AND parser_config = '{}'::jsonb;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '171: % feed rows with an empty parser_config, expected 1 - nothing changed', k; END IF;
END $do$;
SELECT 'config|' || publisher_id || '|' || parser_config::text FROM feeds WHERE publisher_id IN (968, 3138, 1047, 1015, 171) AND enabled ORDER BY publisher_id;
COMMIT;
CREATE TEMP TABLE batch_ids AS
  SELECT id, ((row_number() OVER (ORDER BY id)) - 1) / 500 AS b FROM articles
   WHERE publisher_id IN (968, 3138, 1047, 1015, 171) AND published_at IS NULL AND fetched_at > now() - interval '14 days';
CREATE INDEX ON batch_ids (b); ANALYZE batch_ids;
SELECT 'batches|' || count(*) || ' rows|' || coalesce(max(b) + 1, 0) || ' batches' FROM batch_ids;
SELECT 'start|' || clock_timestamp();
SET statement_timeout = '15s';
SELECT 'DO $w$ BEGIN IF EXISTS (SELECT 1 FROM pg_stat_activity WHERE datname = current_database() AND pid <> pg_backend_pid() AND wait_event_type = ''Lock'' AND now() - query_start > interval ''30 seconds'') THEN RAISE EXCEPTION ''stopping: a session has waited on a lock for over 30s''; END IF; END $w$',
       format('UPDATE articles a SET published_at = a.fetched_at FROM batch_ids i WHERE i.b = %s AND a.id = i.id AND a.published_at IS NULL', b),
       'SELECT pg_sleep(4)'
  FROM generate_series(0, coalesce((SELECT max(b) FROM batch_ids), -1)) b ORDER BY b
\gexec
RESET statement_timeout;
SELECT 'end|' || clock_timestamp();
SELECT 'undated|' || publisher_id || '|' || count(*) || '|in window=' || count(*) FILTER (WHERE fetched_at > now() - interval '14 days')
  FROM articles WHERE publisher_id IN (968, 3138, 1047, 1015, 171) AND published_at IS NULL GROUP BY publisher_id ORDER BY publisher_id;
